/* MYCO FIELD LAB — local-first, optional private Supabase cloud sync.
   Local cache: localStorage and IndexedDB; cloud: per-user RLS and private Storage. */
(() => {
  'use strict';
  const KEY='myco-field-lab-data-v1', DB_NAME='myco-field-lab-photos-v1';
  const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:0});
  const displayDate=date=>{if(!date)return'—';let d=new Date(date+'T12:00:00');return Number.isNaN(+d)?'—':d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});};
  const dateLocal=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
  const dateForDay=n=>{let s=state.settings.startDate;let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+Number(n)-1);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
  const dayForDate=s=>Math.round((new Date(s+'T12:00:00')-new Date(state.settings.startDate+'T12:00:00'))/86400000)+1;
  const icon=(name)=>`<svg aria-hidden="true" class="inline-icon"><use href="#ico-${name}"></use></svg>`;
  const id=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36);
  const stages=['Not started','Incubation','Casing','Fruiting','Harvest','Finished'];
  const statuses=['Not started','Inoculated','Colonizing','Cased','Fruiting','Harvesting','Completed','Discarded'];
  const stepSeed=[
    ['Assessment','Check terrace temperature at 08:00, 14:00, 19:00 for 3 days','Record temperature at bag height, not against the hot GI roof.'],
    ['Assessment','Check terrace humidity at those three times','Use one hygrometer per zone if available.'],
    ['Assessment','Compare under-roof temperature with open outdoor shade','Air and radiant roof heat may differ.'],
    ['Assessment','Inspect roof leaks, rain splash and drainage','No standing water or moisture damage to the roof slab.'],
    ['Setup','Find coolest shaded spot below the metal roof','Keep away from hot roof, terrace floor and direct wind.'],
    ['Setup','Provide insect-screened ventilation','Avoid sealing a plastic enclosure with no fresh air.'],
    ['Setup','Install two separated washable zones and raised stands','The divider does not provide independent temperature control.'],
    ['Setup','Check clean water, drainage and dedicated spray tools','Keep electrical outlets away from moisture.'],
    ['Setup','Verify oyster-specific temperature with supplier','Tropical strains differ; move oyster trial if too hot.'],
    ['Setup','Arrange safe hot-water/steam straw pasteurization','Follow the selected spawn supplier’s method.'],
    ['Hygiene','Clean tools and work area before filling bags','Use food-safe sanitation and clean hands.'],
    ['Hygiene','Prepare labels M01–M06 and O01–O06','Record date and strain on every bag.'],
    ['Hygiene','Confirm how milky casing material will be prepared','Milky requires a correctly treated casing layer.'],
    ['Ready','Verify fresh spawn condition and expiry date','Reject suspect or overheated spawn.'],
    ['Ready','Prepare a safe isolation/disposal plan for contaminated bags','Do not open moldy bags within the growing enclosure.'],
    ['Ready','Take day-0 photos of both zones','Reference the enclosure and each grow bag.']
  ];
  const purchaseSeed=[
    ['Growing inputs','Milky spawn','~1 kg',200],['Growing inputs','Tropical oyster spawn','~1 kg',200],
    ['Growing inputs','Dry paddy straw','6 kg',250],['Growing inputs','Mushroom bags','15–20',150],
    ['Growing inputs','Milky casing material','Small quantity',150],
    ['Monitoring','Digital thermometer/hygrometer','2 units',650],
    ['Environment','Insect mesh and clips','1 set',350],['Environment','Raised supports (reuse if possible)','2 zones',300],
    ['Environment','Hand sprayer','1',200],['Environment','Washable partition or curtain','1',250],
    ['Hygiene','Cleaning supplies, gloves and labels','1 set',250],
    ['Preparation','Pasteurization fuel and utilities','1 batch',350]
  ];
  const makeSeed=()=>({version:1,settings:{name:'12-Bag Terrace Mushroom Trial',startDate:dateLocal(),days:55,location:'Chennai, Tamil Nadu',notes:'Covered metal-sheet terrace · 6 milky + 6 tropical oyster bags'},purchases:purchaseSeed.map((r,i)=>({id:'p'+i,category:r[0],name:r[1],quantity:r[2],estimated:r[3],actual:'',done:false})),setup:stepSeed.map((r,i)=>({id:'s'+i,group:r[0],label:r[1],detail:r[2],done:false})),daily:{},bags:Object.fromEntries([...Array(6)].map((_,i)=>['M'+String(i+1).padStart(2,'0'),{status:'Not started',inoculated:'',dryStraw:500,spawn:'',note:''}]).concat([...Array(6)].map((_,i)=>['O'+String(i+1).padStart(2,'0'),{status:'Not started',inoculated:'',dryStraw:500,spawn:'',note:''}]))),incidents:[],harvests:[],expenses:[]});
  const state=(()=>{try{let s=JSON.parse(localStorage.getItem(KEY));if(s&&s.settings&&s.daily&&s.bags)return s;}catch(_){}return makeSeed();})();
  let currentPage='overview', activeDay=Math.max(1,Math.min(state.settings.days,dayForDate(dateLocal()))), latestPhotos=[], photoUrls=[], saveTimer=0, toastTimer=0, dailyTouched=false;
  const cloud=window.MYCOCloud;
  let cloudConfigured=false, cloudUser=null, cloudRevision=null, cloudPaused=true, cloudBusy=false, cloudQueued=false, cloudTimer=0, cloudError='', remotePhotos=[], cloudInitDone=false;
  const syncedKey=()=>cloudUser?'myco-cloud-synced-'+cloudUser.id:'';
  const importedKey=()=>cloudUser?'myco-cloud-import-confirm-'+cloudUser.id:'';
  const canonical=value=>JSON.stringify(value,(_k,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).sort().map(k=>[k,v[k]])):v);
  const isCleanTrial=()=>Object.keys(state.daily).length===0 && state.purchases.every(x=>!x.done) && state.setup.every(x=>!x.done) && state.incidents.length===0 && state.harvests.length===0 && state.expenses.length===0 && Object.values(state.bags).every(b=>b.status==='Not started'&&!b.note&& !b.inoculated);
  function cloudStatus(text,red=false){let e=$('#save-status'),dot=$('.save-dot');if(e)e.textContent=text;if(dot)dot.style.background=red?'#cd6f49':'#44a977';}
  function replaceState(data){if(!data?.settings||!data?.daily||!data?.bags||!Array.isArray(data.purchases)||!Array.isArray(data.setup))throw new Error('Cloud data has an unexpected structure');Object.keys(state).forEach(x=>delete state[x]);Object.assign(state,JSON.parse(JSON.stringify(data)));activeDay=Math.max(1,Math.min(state.settings.days,dayForDate(dateLocal())));localStorage.setItem(KEY,JSON.stringify(state));render();}
  async function connectCloud(){
    if(!cloudConfigured||!cloudUser)return;
    cloudPaused=true;cloudError='Checking cloud records…';cloudStatus('Connecting to private cloud…');
    try{
      const remote=await cloud.fetchState(); cloudRevision=remote?Number(remote.revision):0;
      const localJSON=canonical(state), remoteJSON=remote?canonical(remote.data):'';
      const last=localStorage.getItem(syncedKey());const pendingImport=!!localStorage.getItem(importedKey());
      if(remote && (localJSON===remoteJSON || isCleanTrial() || last===localJSON)){
        if(localJSON!==remoteJSON)replaceState(remote.data);
        localStorage.setItem(syncedKey(),canonical(state));cloudPaused=false;cloudError='';cloudStatus('Cloud synced · Private');
      }else if(remote && last===remoteJSON && !pendingImport){
        cloudPaused=false;cloudError='Uploading offline changes…';cloudStatus('Syncing offline changes…');await flushCloud();
      }else if(remote){cloudError=pendingImport?'Imported backup needs explicit upload confirmation. Make a new backup before choosing.':'This device and cloud have different records. Create a backup, then choose which version to keep.';cloudStatus('Sync decision needed',true);}
      else{cloudError='Cloud is empty. Click “Upload this device” to create your cloud trial.';cloudStatus('Cloud setup · Upload needed',true);}
      await refreshCloudPhotos();
      if(currentPage==='cloud')render();
      else if(['photos','overview'].includes(currentPage))await loadPhotosIntoView();
    }catch(e){cloudPaused=true;cloudError='Cannot read cloud: '+e.message;cloudStatus('Cloud unavailable · Local backup',true);notify(cloudError,true);if(currentPage==='cloud')render();}
  }
  function queueCloudSave(){if(!cloudUser||cloudPaused)return;cloudStatus('Saving to cloud…');clearTimeout(cloudTimer);cloudTimer=setTimeout(flushCloud,850);}
  async function flushCloud(){
    if(!cloudUser||cloudPaused)return;
    if(cloudBusy){cloudQueued=true;return;}
    cloudBusy=true;const payload=JSON.parse(JSON.stringify(state));const json=canonical(payload);
    try{
      cloudRevision=await cloud.writeState(payload,cloudRevision);
      localStorage.setItem(syncedKey(),json);cloudError='';cloudStatus('Cloud synced · Private');
    }catch(e){cloudError=e.message;cloudStatus(e.message.includes('CONFLICT')?'Sync conflict · Action needed':'Offline · Saved on device',true);
      if(e.message.includes('CONFLICT'))cloudPaused=true;
    }finally{cloudBusy=false;if(cloudQueued||(!cloudPaused&&canonical(state)!==json)){cloudQueued=false;queueCloudSave();}if(currentPage==='cloud')render();}
  }
  async function uploadLocalToCloud(){
    if(!cloudUser)throw new Error('Sign in first.');
    const current=await cloud.fetchState();
    if(current && Number(current.revision)!==cloudRevision){cloudPaused=true;throw new Error('Cloud changed on another device. Load the newest cloud data and check before replacing it.');}
    const message=current?`Overwrite the cloud trial with this device's records? Download a backup first. Other devices may have newer changes.`:`Upload this device's trial to your private cloud now?`;
    if(!confirm(message))return;
    cloudPaused=false;await flushCloud();if(cloudPaused)throw new Error(cloudError||'Cloud upload unsuccessful.');
    await syncLocalPhotos();localStorage.removeItem(importedKey());render();notify('Device records synced to your cloud account');
  }
  async function loadCloud(){
    if(!cloudUser)throw new Error('Sign in first.');
    const remote=await cloud.fetchState();if(!remote)throw new Error('The cloud trial is empty.');
    if(!confirm(`Replace this device's records AND local photos with the cloud version? Export a complete backup first; any unsynced local photo or record will be removed.`))return;
    cloudPaused=true;cloudRevision=Number(remote.revision);await clearPhotos();replaceState(remote.data);localStorage.setItem(syncedKey(),canonical(state));cloudPaused=false;cloudError='';localStorage.removeItem(importedKey());cloudStatus('Cloud synced · Private');await refreshCloudPhotos();render();notify('Loaded latest cloud records');
  }
  async function refreshCloudPhotos(){if(!cloudUser)return;remotePhotos=(await cloud.listPhotos()).map(p=>({...p,originalName:p.original_name,remotePath:p.path}));await refreshPhotos();}
  async function syncLocalPhotos(){
    if(!cloudUser)throw new Error('Sign in first.');
    const local=await getAllPhotos();let existing=new Set(remotePhotos.map(p=>p.id));let completed=0;
    for(const p of local){if(existing.has(p.id))continue;await cloud.uploadPhoto(p);completed++;}
    await refreshCloudPhotos();if(['photos','overview','cloud'].includes(currentPage))render();return completed;
  }
  async function initCloud(){
    cloudConfigured=!!cloud?.configured();
    if(!cloudConfigured){cloudStatus('Device storage · Cloud not configured');return;}
    try{await cloud.init();cloudInitDone=true;cloudUser=cloud.getUser();cloud.onAuthChange(async newUser=>{const prev=cloudUser?.id;cloudUser=newUser;if(cloudUser&&(!prev||prev!==cloudUser.id))await connectCloud();else if(!cloudUser){cloudPaused=true;remotePhotos=[];cloudRevision=null;cloudStatus('Signed out · Device copy only');if(currentPage==='cloud')render();}});
      if(cloudUser)await connectCloud();else{cloudStatus('Sign in for cloud sync');if(currentPage==='cloud')render();}
    }catch(e){cloudError=e.message;cloudStatus('Cloud unavailable · Device copy',true);notify('Cloud connection: '+e.message,true);}
  }

  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));if(!cloudUser||cloudPaused)cloudStatus(cloudUser?'Saved locally · Sync paused':'Saved on this device',Boolean(cloudUser&&cloudPaused));else queueCloudSave();}catch(e){cloudStatus('Local storage full — back up now',true);notify('Could not save locally. Please export a backup.',true);}};
  const notify=(msg,error=false)=>{let n=$('#toast');n.textContent=msg;n.style.background=error?'#993f3f':'#1b4935';n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3500);};
  const pct=(a,b)=>b?Math.round(a/b*100):0;
  const defaultLog=()=>({milkyStage:'Not started',oysterStage:'Not started',readings:{am:{},pm:{},eve:{}},checks:{},notes:'',savedAt:null});
  const getLog=day=>state.daily[day]||defaultLog();
  const hasLog=day=>Boolean(state.daily[day]?.savedAt);
  const loggedDays=()=>Object.keys(state.daily).filter(k=>hasLog(k)).length;
  const openIncidents=()=>state.incidents.filter(x=>x.status!=='Resolved').length;
  const harvestWeight=bag=>state.harvests.filter(h=>!bag||h.bag===bag||(bag.length===1&&h.bag.startsWith(bag))).reduce((t,h)=>t+Number(h.grams||0),0);
  const allSales=()=>state.harvests.reduce((t,h)=>t+(Number(h.sold||0)/1000)*Number(h.price||0),0);
  const allCosts=()=>state.purchases.reduce((t,p)=>t+(p.done?Number(p.actual||p.estimated||0):0),0)+state.expenses.reduce((t,e)=>t+Number(e.amount||0),0);
  const card=(label,number,meta,ico)=>`<div class="card"><div class="card-top"><span class="card-label">${label}</span><span class="card-icon">${icon(ico)}</span></div><div class="metric-number">${number}</div><div class="metric-meta">${meta}</div></div>`;
  const pageHead=(label,title,sub,actions='')=>`<div class="page-top"><div><div class="eyebrow">${label}</div><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p></div>${actions?`<div class="page-top-actions">${actions}</div>`:''}</div>`;
  const empty=(symbol,title,msg)=>`<div class="empty"><div class="empty-symbol">${symbol}</div><h3>${title}</h3><p>${msg}</p></div>`;
  const groupStatus=(milky)=>Object.entries(state.bags).filter(([bid])=>milky?bid[0]==='M':bid[0]==='O');
  const progress=(name,done,total)=>`<div style="margin-bottom:16px"><div class="progress-row"><strong>${name}</strong><span>${done}/${total} complete</span></div><div class="progress-track"><span style="width:${pct(done,total)}%"></span></div></div>`;
  function renderOverview(){
    const pd=state.purchases.filter(p=>p.done).length,sd=state.setup.filter(s=>s.done).length, today=dayForDate(dateLocal()), validToday=today>=1&&today<=state.settings.days;
    const last=Object.keys(state.daily).filter(k=>hasLog(k)).sort((a,b)=>b-a)[0];
    const t=last?getLog(last):null;
    return `${pageHead('YOUR EXPERIMENT / OVERVIEW','Good growing starts with good records.','Every observation helps you decide whether milky or oyster mushrooms suit your Chennai terrace.',`<button class="btn secondary" data-go="reports">${icon('download')} Export data</button>`)}
    <div class="hero"><small>PHASE 01 · CONTROLLED SAMPLE TEST</small><h2>12 bags. Two varieties.<br>One informed decision.</h2><p>Track the full cycle, spot risks early and compare actual yields before investing in a larger mushroom farm.</p><button class="btn" data-go="daily">${icon('plus')} ${validToday?'Log today · Day '+today:'Open daily journal'}</button></div>
    <div class="cards">${card('Days recorded',`${loggedDays()} / ${state.settings.days}`,'Daily environmental observations','calendar')}${card('Purchases complete',`${pd} / ${state.purchases.length}`,'Startup items acquired','cart')}${card('Total harvested',`${(harvestWeight()/1000).toFixed(2)} kg`,'All bags · all flushes','sprout')}${card('Open abnormalities',openIncidents(),'Incidents awaiting resolution','alert')}</div>
    <div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>Launch readiness</h2><p class="panel-caption">Complete these before inoculation.</p></div><span class="pill ${sd===state.setup.length?'':'amber'}">${pct(sd,state.setup.length)}% ready</span></div>${progress('Purchasing',pd,state.purchases.length)}${progress('Setup preparation',sd,state.setup.length)}<div class="row-spread"><button class="btn secondary small" data-go="purchases">Review purchases ${icon('arrow')}</button><button class="btn secondary small" data-go="setup">Setup checklist ${icon('arrow')}</button></div></section>
    <section class="panel"><div class="panel-head"><div><h2>Last field observations</h2><p class="panel-caption">Latest recorded day, not real-time sensor readings.</p></div></div>${t?`<div class="overview-row"><div><b>Day ${last} · ${displayDate(dateForDay(last))}</b><small>Milky: ${esc(t.milkyStage)} · Oyster: ${esc(t.oysterStage)}</small></div><span class="pill">Recorded</span></div>${['am','pm','eve'].map((slot,i)=>{let r=t.readings?.[slot]||{};return `<div class="overview-row"><div><b>${['Morning','Afternoon','Evening'][i]}</b><small>Milky ${r.mt||'—'}°C · Oyster ${r.ot||'—'}°C</small></div><small>${r.mh||'—'}% / ${r.oh||'—'}% RH</small></div>`}).join('')}`:empty('🌡','No measurements yet','Begin with a 3-day roof-temperature assessment before filling the bags.')}</section></div>
    <div class="grid-equal"><section class="panel"><div class="panel-head"><h2>Meet the 12 bags</h2><button class="btn small secondary" data-go="bags">Open bag tracker</button></div>${['Milky','Oyster'].map((type,i)=>{let b=groupStatus(i===0);let started=b.filter(([,x])=>x.status!=='Not started').length;return `<div class="overview-row"><div><b>${type} mushroom</b><small>${i===0?'M01–M06':'O01–O06'} · 6 bags</small></div><span class="pill ${i===0?'':'blue'}">${started} started</span></div>`}).join('')}<div class="callout warn" style="margin:17px 0 0"><strong>Heat caution:</strong> A GI roof can radiate heat even without direct sunlight. Milky and tropical oyster fruiting temperatures differ. Use bag-height measurements to decide if oyster needs relocation.</div></section>
    <section class="panel"><div class="panel-head"><h2>Latest abnormalities</h2><button class="btn small secondary" data-go="incidents">Report an issue</button></div>${state.incidents.length?state.incidents.slice(-3).reverse().map(it=>`<div class="overview-row"><div><b>${esc(it.type)}</b><small>${esc(it.bag||'General')} · ${displayDate(it.date)} · ${esc(it.status)}</small></div><span class="pill ${it.severity==='High'?'red':'amber'}">${esc(it.severity)}</span></div>`).join(''):empty('✓','No incidents reported','Log unusual growth, odors, pests, excessive heat, or water accumulation here.')}</section></div>
    <section class="panel"><div class="panel-head"><h2>Photo journal</h2><button class="btn small secondary" data-go="photos">Open journal</button></div>${latestPhotos.length?`<div class="photo-grid">${latestPhotos.slice(0,4).map(p=>photoTile(p)).join('')}</div>`:empty('📷','Capture your baseline','Add images of the roof, each zone, and the bags before Day 1.')}</section>`;
  }
  function renderPurchases(){let bought=state.purchases.filter(p=>p.done).length,spent=state.purchases.filter(p=>p.done).reduce((n,p)=>n+Number(p.actual||p.estimated||0),0),estimate=state.purchases.reduce((n,p)=>n+Number(p.estimated||0),0);
    return `${pageHead('STAGE 01 / BUYING','Purchasing checklist','Check off items, update real prices and add any extra costs. No vendor prices are guaranteed.',`<button class="btn secondary" id="add-purchase">${icon('plus')} Add item</button>`)}
    <div class="cards">${card('Purchased',`${bought}/${state.purchases.length}`,'Checklist progress','check')}${card('Actual paid',money(spent),'Actual price when entered, otherwise estimate','cart')}${card('Estimated basket',money(estimate),'User-editable planned cost','report')}${card('Pilot ceiling',money(5000),'Suggested sample-test spend cap','settings')}</div>
    <div class="callout">This is a <strong>sample-test budget</strong>, not a quotation. Some equipment may be reused. Enter actual amounts including delivery; keep receipts and check spawn strain and freshness.</div>
    <section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Buy</th><th>Item</th><th>Qty</th><th class="right">Budget ₹</th><th class="right">Paid ₹</th><th></th></tr></thead><tbody>${state.purchases.map(p=>`<tr><td><input type="checkbox" data-purch-check="${p.id}" ${p.done?'checked':''} aria-label="Purchased ${esc(p.name)}"></td><td><b>${esc(p.name)}</b><small style="display:block;color:#8a9a8e">${esc(p.category)}</small></td><td>${esc(p.quantity)}</td><td class="right"><input type="number" min="0" step="1" data-purch-cost="${p.id}" value="${Number(p.estimated)||0}" aria-label="Estimate ${esc(p.name)}"></td><td class="right"><input type="number" min="0" step="1" placeholder="—" data-purch-actual="${p.id}" value="${p.actual===''?'':Number(p.actual)}" aria-label="Actual ${esc(p.name)}"></td><td>${p.id.startsWith('new')?`<button class="icon-btn" data-del-purchase="${p.id}" title="Remove">${icon('trash')}</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>
    <section class="panel"><h2>Extra purchase</h2><form id="new-purchase" class="form-grid four" style="margin-top:13px"><div class="form-cell"><label class="label">Item name</label><input name="name" required maxlength="120" placeholder="e.g. extra trays"></div><div class="form-cell"><label class="label">Quantity</label><input name="quantity" placeholder="2 pieces"></div><div class="form-cell"><label class="label">Budget (₹)</label><input name="estimated" type="number" min="0" value="0"></div><div class="form-cell" style="display:flex;align-items:end"><button type="submit" class="btn">Add to list</button></div></form></section>`;
  }
  function renderSetup(){let done=state.setup.filter(s=>s.done).length,groups=[...new Set(state.setup.map(x=>x.group))];return `${pageHead('STAGE 02 / PREPARATION','Setup & preflight','A practical sequence for your shaded metal-roof terrace before you start inoculating the 12 bags.')}${progress('Readiness',done,state.setup.length)}<div class="callout warn"><b>Safety first:</b> Do not trap heat under airtight plastic. Protect the terrace waterproofing; never place live electrical connections where spraying or rain can reach them. Hot-water pasteurization can cause burns.</div>${groups.map(g=>{let rows=state.setup.filter(s=>s.group===g);return `<section class="panel"><div class="panel-head"><h2>${esc(g)}</h2><span class="badge-count">${rows.filter(r=>r.done).length}/${rows.length} done</span></div><div class="check-list">${rows.map(s=>`<label class="check-row ${s.done?'done':''}"><input type="checkbox" data-setup-check="${s.id}" ${s.done?'checked':''}><span><b>${esc(s.label)}</b><small>${esc(s.detail)}</small></span></label>`).join('')}</div></section>`}).join('')}`;}
  const readingFields=[['mt','Milky °C','number',-5,60],['mh','Milky RH %','number',0,100],['ot','Oyster °C','number',-5,60],['oh','Oyster RH %','number',0,100]];
  function stageSelect(name,value){return `<select name="${name}" aria-label="${name}">${stages.map(s=>`<option ${s===value?'selected':''}>${esc(s)}</option>`).join('')}</select>`;}
  function dailyAlerts(l){let msgs=[]; for(let [name,stage,prefix,min,max] of [['Milky',l.milkyStage,'m',28,35],['Oyster',l.oysterStage,'o',25,30]]){if(!['Fruiting','Harvest'].includes(stage))continue;['am','pm','eve'].forEach(slot=>{let v=l.readings?.[slot]||{};let c=Number(v[prefix+'t']),rh=Number(v[prefix+'h']);if(v[prefix+'t']!==''&&v[prefix+'t']!==undefined&&(c<min||c>max))msgs.push(`${name} ${slot.toUpperCase()} temperature ${c}°C outside illustrative fruiting band ${min}–${max}°C.`);if(v[prefix+'h']!==''&&v[prefix+'h']!==undefined&&(rh<80||rh>95))msgs.push(`${name} ${slot.toUpperCase()} RH ${rh}% outside broad fruiting observation band 80–95%.`);});}return msgs;}
  function renderDaily(){let l=getLog(activeDay),d=dateForDay(activeDay),alerts=dailyAlerts(l);return `${pageHead('STAGE 03 / DAILY JOURNAL','Daily monitoring','Record temperature and relative humidity in each zone at three times per day. Check water spray, hygiene and any changes.')}
    <section class="panel"><div class="day-toolbar"><div><span class="eyebrow" style="margin:0">SELECT EXPERIMENT DAY</span><div class="day-title">Day ${activeDay} <span class="subtle" style="font-size:13px;font-weight:600">· ${displayDate(d)}</span></div></div><div class="page-top-actions"><button class="btn secondary small" data-day="${Math.max(1,activeDay-1)}" ${activeDay===1?'disabled':''}>← Previous</button><button class="btn secondary small" data-day="${Math.min(state.settings.days,activeDay+1)}" ${activeDay===state.settings.days?'disabled':''}>Next →</button></div></div>
    <div class="day-strip" role="group" aria-label="Choose experiment day">${Array.from({length:state.settings.days},(_,i)=>`<button class="day-chip ${i+1===activeDay?'active':''} ${hasLog(i+1)?'has-log':''}" data-day="${i+1}" aria-label="Day ${i+1}, ${displayDate(dateForDay(i+1))}" title="${displayDate(dateForDay(i+1))}">${i+1}</button>`).join('')}</div><div class="row-spread"><small class="subtle">● Green dot = saved monitoring entry</small><button class="btn secondary small" data-day="${Math.max(1,Math.min(state.settings.days,dayForDate(dateLocal())))}">Jump to today</button></div></section>
    ${alerts.length?`<div class="callout warn"><b>Review these readings:</b><ul style="margin:7px 0 0;padding-left:18px">${alerts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>These are flags, not diagnoses; check your strain supplier’s specific target and measurement accuracy.</small></div>`:''}
    <form id="daily-form" class="panel"><div class="panel-head"><div><h2>Crop stage for this day</h2><p class="panel-caption">Humidity and spraying needs differ between closed incubation bags and exposed fruiting bodies.</p></div><span class="pill ${hasLog(activeDay)?'':'gray'}">${hasLog(activeDay)?'Saved':'Not entered'}</span></div><div class="form-grid two"><div><label class="label">Milky stage</label>${stageSelect('milkyStage',l.milkyStage)}</div><div><label class="label">Oyster stage</label>${stageSelect('oysterStage',l.oysterStage)}</div></div>
      <div class="line-sep"></div><h2>Temperature & humidity</h2><p class="panel-caption" style="margin-bottom:14px">Enter actual observations at bag height. Leave a field empty if you did not measure it.</p><div class="reading-grid">${[['am','08:00','Morning'],['pm','14:00','Afternoon'],['eve','19:00','Evening']].map(([k,time,label])=>{let r=l.readings?.[k]||{};return `<div class="reading-card"><h3>${label} <small>${time}</small></h3><div class="reading-metrics">${readingFields.map(([key,title,type,min,max])=>`<div><label for="${k}-${key}">${title}</label><input id="${k}-${key}" name="${k}-${key}" type="${type}" step="0.1" min="${min}" max="${max}" placeholder="—" value="${esc(r[key]??'')}"></div>`).join('')}</div></div>`}).join('')}</div>
      <div class="line-sep"></div><div class="panel-head"><div><h2>Daily care checklist</h2><p class="panel-caption">Tick only what was done or verified today.</p></div></div><div class="water-checks">${[['msprayAM','Milky: morning humidity / spray check'],['msprayPM','Milky: evening humidity / spray check'],['osprayAM','Oyster: morning humidity / spray check'],['osprayPM','Oyster: evening humidity / spray check'],['ventilated','Fresh air / ventilation checked'],['clean','Drainage and standing water checked'],['bagInspection','All 12 bags inspected'],['hygiene','Hands / tools cleaned']].map(([k,title])=>`<label class="check-tile"><input type="checkbox" name="${k}" ${l.checks?.[k]?'checked':''}>${title}</label>`).join('')}</div>
      <div class="callout" style="margin-top:15px"><strong>Spray safety:</strong> During closed-bag incubation, do not soak the bags. During fruiting, maintain humidity with gentle mist in the enclosure without leaving mushrooms constantly wet. Excess humidity without ventilation increases contamination risk. A checked box means the moisture check was performed, not that spraying was necessarily needed.</div>
      <div style="margin-top:14px"><label class="label">Observations / remarks</label><textarea name="notes" rows="4" maxlength="4000" placeholder="Mycelium color, pinning, bag changes, smell, pests, condensation, ambient roof heat, actions taken...">${esc(l.notes)}</textarea></div>
      <div class="row-spread" style="margin-top:15px;flex-wrap:wrap"><small class="subtle" id="daily-save-hint">Changes auto-save after entry; use Save now to confirm.</small><div class="page-top-actions"><button type="button" class="btn secondary" data-go="photos">${icon('camera')} Day photos</button><button type="button" class="btn secondary" data-go="incidents">${icon('alert')} Report abnormality</button><button type="submit" class="btn">${icon('check')} Save now</button></div></div>
    </form>`;
  }
  function renderBags(){return `${pageHead('STAGE 04 / PER-BAG RECORDS','Bag tracker','All 12 bags stay individually identified. Set the real inoculation date, growth status, and observations.',`<button class="btn secondary" data-go="reports">${icon('report')} Harvest records</button>`)}
    <div class="callout">Starter substrate assumption: <strong>500 g of dry straw per bag</strong> (6 kg total). Adjust each bag’s actual weight below; compare yield against dry-substrate weight, not a vague “one bag” estimate. Bag records save automatically.</div>
    ${[['M','MILKY MUSHROOM · 6 BAGS'],['O','TROPICAL OYSTER · 6 BAGS']].map(([prefix,title])=>`<section class="panel"><div class="panel-head"><h2>${title}</h2><span class="pill ${prefix==='M'?'':'blue'}">${(harvestWeight(prefix)/1000).toFixed(2)} kg harvested</span></div><div class="bag-grid">${Object.entries(state.bags).filter(([bid])=>bid.startsWith(prefix)).map(([bid,b])=>`<div class="bag-card"><div class="row-spread"><span class="bag-id ${prefix==='O'?'o':''}">${bid}</span><span class="tiny">${Math.round(harvestWeight(bid))} g harvested</span></div><div style="margin-top:12px"><label class="label">Current bag status</label><select data-bag-field="status" data-bag="${bid}">${statuses.map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-grid two"><div><label class="label">Inoculated</label><input data-bag-field="inoculated" data-bag="${bid}" type="date" value="${esc(b.inoculated)}"></div><div><label class="label">Dry straw (g)</label><input data-bag-field="dryStraw" data-bag="${bid}" type="number" min="0" step="1" value="${esc(b.dryStraw)}"></div><div><label class="label">Spawn (g)</label><input data-bag-field="spawn" data-bag="${bid}" type="number" min="0" step="1" placeholder="Actual" value="${esc(b.spawn)}"></div><div><label class="label">Health note</label><input data-bag-field="note" data-bag="${bid}" type="text" maxlength="240" value="${esc(b.note)}" placeholder="e.g. healthy / slow"></div></div><div class="row-spread" style="margin-top:12px"><button class="btn secondary small" data-quick-harvest="${bid}">+ Harvest</button><button class="btn ghost small" data-quick-photo="${bid}">+ Photo</button></div></div>`).join('')}</div></section>`).join('')}`;}
  function photoTile(p){let url=photoUrls.find(x=>x.id===p.id)?.url;return `<article class="photo-card">${url?`<img src="${url}" alt="${esc(p.caption||'Mushroom progress image')}" data-view-photo="${p.id}" loading="lazy">`:'<div style="height:130px;background:#f1f4ef"></div>'}<button class="delete-photo" data-delete-photo="${p.id}" title="Delete photo" aria-label="Delete photo">×</button><div class="photo-caption"><strong>${esc(p.bag||'General')} · Day ${esc(p.day||'—')}</strong><small>${displayDate(p.date)} · ${esc(p.caption||'No caption')}</small></div></article>`;}
  function renderPhotos(){let photoCount=latestPhotos.length;return `${pageHead('STAGE 05 / VISUAL EVIDENCE','Photo journal','Add day-by-day photos of bags, zone conditions and any unusual changes. Images are kept locally and also in private cloud storage when synced.',`<span class="pill blue">${photoCount} saved photos</span>`)}
    <div class="callout warn"><b>How photos are stored:</b> Images are resized and saved locally in this browser’s IndexedDB. They are <b>not</b> uploaded to GitHub and are <b>not</b> synced across devices. Export a full JSON backup regularly; clearing browser site data can erase photos.</div>
    <section class="panel"><div class="panel-head"><h2>Add field photos</h2><span class="pill">Up to 12 images per batch</span></div><form id="photo-form"><div class="form-grid"><div><label class="label">Observation day</label><select name="day" id="photo-day">${Array.from({length:state.settings.days},(_,i)=>`<option value="${i+1}" ${i+1===activeDay?'selected':''}>Day ${i+1} · ${displayDate(dateForDay(i+1))}</option>`).join('')}</select></div><div><label class="label">Bag / zone</label><select name="bag" id="photo-bag">${['General / terrace','Milky zone','Oyster zone',...Object.keys(state.bags)].map(v=>`<option ${v==='General / terrace'?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div><label class="label">Photo note</label><input name="caption" maxlength="140" placeholder="e.g. First white colonization"></div></div><div class="dropzone" style="margin:14px 0"><label class="label" for="photo-input">Select or take photos</label><input id="photo-input" name="photos" type="file" accept="image/*" multiple required><p>JPG/PNG/HEIC where browser-supported. Each image is compressed for storage; original full-resolution files are not retained by this app.</p></div><button type="submit" class="btn">${icon('camera')} Save photos</button><span class="small-note" id="photo-status" style="margin-left:10px"></span></form></section>
    <section class="panel"><div class="panel-head"><h2>Saved images</h2><div class="toolbar" style="margin:0"><label class="label" for="photo-filter" style="margin:0">Filter</label><select id="photo-filter" style="min-height:32px;width:auto"><option value="all">All days</option>${Array.from({length:state.settings.days},(_,i)=>`<option value="${i+1}">Day ${i+1}</option>`).join('')}</select></div></div><div id="photo-list">${photoCount?`<div class="photo-grid">${latestPhotos.map(photoTile).join('')}</div>`:empty('📷','No photos saved yet','Capture your baseline terrace layout, healthy colonization and each harvest.')}</div></section>`;}
  function renderIncidents(){return `${pageHead('STAGE 06 / TROUBLESHOOTING','Abnormality & incident log','Record unusual mold, excess heat, pests, strange odor or other changes. Document actions and confirm follow-up.',`<span class="pill ${openIncidents()?'red':''}">${openIncidents()} open</span>`)}
    <div class="callout warn"><strong>Potential contamination:</strong> Isolate suspect bags promptly, avoid opening them in the growing area and follow safe disposal/hygiene advice. Photos and readings cannot reliably identify a pathogen. Do not consume produce from visibly contaminated bags.</div>
    <section class="panel"><div class="panel-head"><h2>New incident / abnormality report</h2></div><form id="incident-form" class="form-grid"><div><label class="label">Date observed</label><input name="date" type="date" required value="${dateLocal()}"></div><div><label class="label">Affected bag / zone</label><select name="bag"><option>General terrace</option><option>Milky zone</option><option>Oyster zone</option>${Object.keys(state.bags).map(b=>`<option>${b}</option>`).join('')}</select></div><div><label class="label">Severity</label><select name="severity"><option>Low</option><option selected>Medium</option><option>High</option></select></div><div><label class="label">Observed abnormality</label><select name="type"><option>Unusual growth / suspected mold</option><option>High temperature</option><option>Low temperature</option><option>Humidity problem</option><option>Unpleasant odor</option><option>Pest / insect activity</option><option>Water pooling / leakage</option><option>Slow colonization</option><option>Physical damage</option><option>Other</option></select></div><div><label class="label">Follow-up date</label><input name="followup" type="date"></div><div><label class="label">Status</label><select name="status"><option>Open</option><option>Monitoring</option><option>Resolved</option></select></div><div class="form-cell full"><label class="label">What happened? (detailed remarks)</label><textarea name="observation" maxlength="4000" required placeholder="Color, smell, location, amount, timeline, readings, photo reference..."></textarea></div><div class="form-cell full"><label class="label">Corrective action / next check</label><textarea name="action" maxlength="4000" placeholder="e.g. Isolated M03, cleaned nearby surfaces, rechecked air flow..."></textarea></div><div class="form-cell full"><button class="btn" type="submit">${icon('plus')} Save incident report</button></div></form></section>
    <section class="panel"><div class="panel-head"><h2>Incident history</h2><span class="pill">${state.incidents.length} recorded</span></div>${state.incidents.length?state.incidents.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(it=>`<article class="incident-card"><div class="row-spread"><div><span class="incident-heading">${esc(it.type)}</span><div class="incident-meta"><span>${displayDate(it.date)}</span><span>· ${esc(it.bag)}</span><span>· ${esc(it.severity)} severity</span>${it.followup?`<span>· Follow up ${displayDate(it.followup)}</span>`:''}</div></div><span class="pill ${it.status==='Resolved'?'':'amber'}">${esc(it.status)}</span></div><p><b>Observation:</b> ${esc(it.observation)}</p>${it.action?`<p><b>Action:</b> ${esc(it.action)}</p>`:''}<div class="row-spread" style="margin-top:13px"><select style="width:auto;min-height:32px;font-size:11px" data-incident-status="${it.id}">${['Open','Monitoring','Resolved'].map(v=>`<option ${v===it.status?'selected':''}>${v}</option>`).join('')}</select><button class="btn ghost small" data-del-incident="${it.id}">Delete</button></div></article>`).join(''):empty('✓','No abnormality records','Use the form above as soon as you notice an issue, even if you are unsure of the cause.')}</section>`;}
  function chartTemp(){let pts=Object.keys(state.daily).filter(k=>hasLog(k)).sort((a,b)=>a-b).map(k=>{let r=state.daily[k].readings?.pm||{};return{day:Number(k),m:!isNaN(parseFloat(r.mt))?Number(r.mt):null,o:!isNaN(parseFloat(r.ot))?Number(r.ot):null}}).filter(x=>x.m!==null||x.o!==null);if(!pts.length)return empty('📈','Not enough readings','Enter afternoon temperatures in Daily monitoring to see your temperature trend.');let all=pts.flatMap(x=>[x.m,x.o]).filter(v=>v!==null),low=Math.floor(Math.min(...all,22)-2),high=Math.ceil(Math.max(...all,37)+2),x=d=>36+(d-1)/Math.max(1,state.settings.days-1)*580,y=v=>175-((v-low)/Math.max(1,high-low))*142;const plot=key=>{let path='',segment=false;pts.forEach(p=>{if(p[key]===null){segment=false;return;}path+=(segment?'L':'M')+x(p.day).toFixed(1)+','+y(p[key]).toFixed(1)+' ';segment=true;});return path;};return `<div class="mini-chart"><svg viewBox="0 0 640 210" role="img" aria-label="Afternoon temperature over observation days for milky and oyster zones">${[0,1,2,3,4].map(j=>{let v=low+j*(high-low)/4;return `<line x1="36" x2="622" y1="${y(v)}" y2="${y(v)}" stroke="#e2eae1" stroke-dasharray="4 4"/><text x="27" y="${y(v)+3}" text-anchor="end" fill="#92a398" font-size="10">${v.toFixed(0)}°</text>`}).join('')}<path d="${plot('m')}" fill="none" stroke="#448b60" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="${plot('o')}" fill="none" stroke="#4987b7" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${pts.map(p=>`${p.m===null?'':`<circle cx="${x(p.day)}" cy="${y(p.m)}" r="3" fill="#448b60"/>`}${p.o===null?'':`<circle cx="${x(p.day)}" cy="${y(p.o)}" r="3" fill="#4987b7"/>`}`).join('')}<text x="35" y="200" fill="#92a398" font-size="10">Day 1</text><text x="622" y="200" text-anchor="end" fill="#92a398" font-size="10">Day ${state.settings.days}</text></svg></div>`;}
  function renderReports(){const total=harvestWeight(),milky=harvestWeight('M'),oyster=harvestWeight('O'),sold=state.harvests.reduce((s,h)=>s+Number(h.sold||0),0);return `${pageHead('STAGE 07 / RESULTS','Harvest, reports & backup','Evaluate the true yield and sales, monitor conditions and protect your farm records with regular backups.')}
    <div class="cards">${card('Milky harvest',`${(milky/1000).toFixed(2)} kg`,'M01–M06 across flushes','sprout')}${card('Oyster harvest',`${(oyster/1000).toFixed(2)} kg`,'O01–O06 across flushes','sprout')}${card('Recorded sales',money(allSales()),`${(sold/1000).toFixed(2)} kg sold`,'cart')}${card('Total costs entered',money(allCosts()),'Bought supplies and running expenses','report')}</div>
    <div class="grid-two"><section class="panel"><div class="panel-head"><h2>Afternoon temperature trend</h2><div class="legend"><span><i></i>Milky</span><span><i class="blue"></i>Oyster</span></div></div>${chartTemp()}<p class="small-note">Recorded readings only, not a continuous temperature sensor. Temperature thresholds depend on crop stage and oyster strain.</p></section>
    <section class="panel"><div class="panel-head"><h2>Trial performance</h2></div><div class="report-rows"><span>Daily records</span><strong>${loggedDays()} / ${state.settings.days}</strong><span>Total yield</span><strong>${(total/1000).toFixed(3)} kg</strong><span>Estimated dry straw</span><strong>${Object.values(state.bags).reduce((s,b)=>s+Number(b.dryStraw||0),0)/1000} kg</strong><span>Biological efficiency (fresh/dry)</span><strong>${(total/Math.max(1,Object.values(state.bags).reduce((s,b)=>s+Number(b.dryStraw||0),0))*100).toFixed(1)}%</strong><span>Unresolved reports</span><strong>${openIncidents()}</strong><span>Revenue minus recorded expenses</span><strong>${money(allSales()-allCosts())}</strong></div><p class="small-note">This is a sample-batch cash summary, not monthly net profit. Owner wages, depreciation, unrecorded utilities, rent and tax are not automatically included.</p></section></div>
    <section class="panel"><div class="panel-head"><h2>Record mushroom harvest</h2></div><form id="harvest-form" class="form-grid four"><div><label class="label">Bag</label><select name="bag">${Object.keys(state.bags).map(b=>`<option>${b}</option>`).join('')}</select></div><div><label class="label">Date</label><input name="date" type="date" value="${dateLocal()}" required></div><div><label class="label">Flush #</label><input name="flush" type="number" value="1" min="1" max="10" required></div><div><label class="label">Fresh harvested (g)</label><input name="grams" type="number" min="0" step="1" required placeholder="e.g. 320"></div><div><label class="label">Sold (g)</label><input name="sold" type="number" min="0" step="1" value="0"></div><div><label class="label">Sale price (₹/kg)</label><input name="price" type="number" min="0" step="1" value="0"></div><div><label class="label">Remarks</label><input name="note" maxlength="200" placeholder="Quality, buyer, etc."></div><div style="display:flex;align-items:end"><button class="btn" type="submit">Add harvest</button></div></form><div class="table-wrap" style="margin-top:17px"><table class="table"><thead><tr><th>Date</th><th>Bag</th><th>Flush</th><th class="right">Harvest g</th><th class="right">Sold g</th><th class="right">Revenue</th><th></th></tr></thead><tbody>${state.harvests.length?state.harvests.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(h=>`<tr><td>${displayDate(h.date)}</td><td><b>${esc(h.bag)}</b></td><td>#${esc(h.flush)}</td><td class="right">${esc(h.grams)}</td><td class="right">${esc(h.sold)}</td><td class="right">${money(Number(h.sold||0)*Number(h.price||0)/1000)}</td><td><button class="icon-btn" data-del-harvest="${h.id}" title="Remove harvest">${icon('trash')}</button></td></tr>`).join(''):'<tr><td colspan="7">No harvests recorded yet.</td></tr>'}</tbody></table></div></section>
    <section class="panel"><div class="panel-head"><h2>Other running expenses</h2></div><form id="expense-form" class="form-grid four"><div><label class="label">Date</label><input name="date" type="date" value="${dateLocal()}" required></div><div><label class="label">Description</label><input name="name" required maxlength="120" placeholder="e.g. delivery, electricity"></div><div><label class="label">Amount (₹)</label><input name="amount" type="number" min="0" step="1" required></div><div style="display:flex;align-items:end"><button type="submit" class="btn">Add expense</button></div></form>${state.expenses.length?`<div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Date</th><th>Expense</th><th class="right">Amount</th><th></th></tr></thead><tbody>${state.expenses.map(e=>`<tr><td>${displayDate(e.date)}</td><td>${esc(e.name)}</td><td class="right">${money(e.amount)}</td><td><button class="icon-btn" data-del-expense="${e.id}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>`:''}</section>
    <section class="panel"><div class="panel-head"><h2>Reports & safe backups</h2></div><div class="callout warn"><b>GitHub Pages does not provide a database:</b> Records and images are stored only in this browser. A different phone or laptop cannot see them automatically. Export a JSON backup (including images) after each photo session, and store it in a safe place. You can restore on another device.</div><div class="report-actions"><button class="btn" id="export-backup">${icon('download')} Download full JSON backup + photos</button><button class="btn secondary" id="import-backup">Import saved backup</button><button class="btn secondary" id="export-daily">Download daily CSV</button><button class="btn secondary" id="export-harvest">Download harvest CSV</button><button class="btn secondary" id="export-incidents">Download incidents CSV</button><button class="btn secondary" id="print-report">${icon('report')} Print / Save PDF report</button></div><p class="small-note">Backups may become large if you add many photos. Imported backups replace this device’s current project and images after confirmation. Keep a copy of your previous backup.</p></section>`;
  }
  function renderSettings(){let s=state.settings;return `${pageHead('PROJECT / CONFIGURATION','Trial settings','Choose your actual inoculation start date and trial duration. Day 1 is always the start date you enter.')}
    <section class="panel"><form id="settings-form" class="form-grid two"><div class="form-cell full"><label class="label">Project name</label><input name="name" value="${esc(s.name)}" maxlength="140" required></div><div><label class="label">Trial Day 1</label><input name="startDate" type="date" value="${esc(s.startDate)}" required></div><div><label class="label">Planned experiment duration (days)</label><input name="days" type="number" min="30" max="90" value="${esc(s.days)}" required></div><div class="form-cell full"><label class="label">Location / environment</label><input name="location" value="${esc(s.location)}" maxlength="150"></div><div class="form-cell full"><label class="label">Trial notes</label><textarea name="notes" maxlength="2000">${esc(s.notes)}</textarea></div><div class="form-cell full"><button class="btn" type="submit">${icon('check')} Save settings</button></div></form></section><div class="callout warn"><b>Backups are still important.</b> ${cloudUser?'Cloud sync is enabled when connected. Offline changes are cached on this device until synced.':'Until you sign into Cloud Sync, this device holds the only copy.'} Keep an external backup, especially before resetting or changing phones.</div><section class="panel"><div class="panel-head"><h2>Project maintenance</h2></div><div class="report-actions"><button id="settings-backup" class="btn secondary">${icon('download')} Create complete backup</button><button class="btn ghost" data-go="reports">Open export tools</button><button id="reset-data" class="btn warn">Reset local project</button></div><p class="small-note">Reset is irreversible for this browser. A backup should be downloaded and verified before resetting.</p></section>`;}
  function renderCloud(){const cfg=cloud?.getConfig()||{url:'',key:''};const signed=!!cloudUser;return `${pageHead('CLOUD / PRIVATE SYNC','Cloud sync & account','Securely sync the 12-bag field journal and private photo evidence between your phone and laptop.')}<div class="callout ${cloudError?'warn':''}"><b>${signed?'Signed in as '+esc(cloudUser.email||'farm owner'):'Cloud account not signed in'}</b><br>${esc(cloudError|| (signed?'Your edits sync automatically when online. Photos are uploaded to private cloud storage.':'Set up Supabase once, then sign in using an email magic link. You can continue using local mode until then.'))}</div>
  <section class="panel"><div class="panel-head"><h2>Step 1 · Connect your Supabase project</h2><span class="pill ${cloudConfigured?'':'amber'}">${cloudConfigured?'Configured':'Not configured'}</span></div><p class="small-note">Paste only the Project URL and <b>publishable</b> key; never paste a service_role or secret key. Run the provided supabase_setup.sql in Supabase first.</p><form id="cloud-config" class="form-grid two" style="margin-top:15px"><div><label class="label">Supabase project URL</label><input name="url" type="url" required placeholder="https://xxxxx.supabase.co" value="${esc(cfg.url)}"></div><div><label class="label">Publishable / anon key</label><input name="key" type="text" required spellcheck="false" placeholder="sb_publishable_..." value="${esc(cfg.key)}"></div><div class="form-cell full"><button class="btn" type="submit">Save configuration & reconnect</button></div></form><p class="small-note">To avoid entering these details on each device, fill them into config.js before uploading the website to GitHub. These are public client values, protected by database RLS policies.</p></section>
  <section class="panel"><div class="panel-head"><h2>Step 2 · Private email sign-in</h2><span class="pill ${signed?'':'gray'}">${signed?'Authenticated':'Not signed in'}</span></div>${signed?`<p class="small-note">${esc(cloudUser.email||'')} · Each account sees only its own records.</p><div class="report-actions" style="margin-top:14px"><button class="btn secondary" id="cloud-signout">Sign out</button></div>`:`<form id="cloud-login" class="form-grid two"><div><label class="label">Your email address</label><input name="email" type="email" required placeholder="you@example.com"></div><div style="align-self:end"><button class="btn" type="submit" ${cloudInitDone?'':'disabled'}>Email me a sign-in link</button></div></form><p class="small-note">Open the email link in a browser. Configure GitHub Pages URL in Supabase Auth → URL Configuration first.</p>`}</section>
  <section class="panel"><div class="panel-head"><h2>Step 3 · Sync and migrate safely</h2></div><p class="small-note">To preserve existing data, this app never silently overwrites records if your phone and cloud have both changed. Download a backup before replacing anything.</p><div class="report-actions" style="margin-top:15px"><button class="btn secondary" id="cloud-sync-now" ${signed&&!cloudPaused?'':'disabled'}>Sync local changes</button><button class="btn secondary" id="cloud-photos" ${signed?'':'disabled'}>Upload pending photos</button><button class="btn" id="cloud-upload" ${signed?'':'disabled'}>Upload this device to cloud</button><button class="btn ghost" id="cloud-load" ${signed?'':'disabled'}>Load cloud onto this device</button><button class="btn ghost" id="cloud-backup">Download full backup</button></div><p class="small-note">Status: ${esc(cloudUser?(cloudPaused?'Sync paused · '+cloudError:'Connected · revision '+cloudRevision):'Local storage mode')} · ${remotePhotos.length} photos listed in cloud</p></section>
  <section class="panel"><div class="panel-head"><h2>Data privacy and limitations</h2></div><p class="small-note">Supabase holds your monitoring data and photos with per-user access policies. GitHub hosts only the website code. A local cache remains on this device for offline entry. If you sign out, the device cache is not erased; use a trusted phone or computer. Concurrent changes are flagged instead of silently overwritten. Keep backups, because cloud sync is not a permanent archival guarantee.</p></section>`;}
  const renderers={overview:renderOverview,purchases:renderPurchases,setup:renderSetup,daily:renderDaily,bags:renderBags,photos:renderPhotos,incidents:renderIncidents,reports:renderReports,settings:renderSettings,cloud:renderCloud};
  function render(){photoUrls.filter(p=>p.objectUrl).forEach(p=>URL.revokeObjectURL(p.url));photoUrls=[];if(!renderers[currentPage])currentPage='overview';$('#page').innerHTML=renderers[currentPage]();$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));const titles={overview:'Overview',purchases:'Purchasing',setup:'Setup checklist',daily:'Daily monitoring',bags:'Bag tracker',photos:'Photo journal',incidents:'Abnormality log',reports:'Reports & backup',settings:'Trial settings',cloud:'Cloud sync'};$('#breadcrumb-current').textContent=titles[currentPage];let n=$('#nav-open-incidents');n.textContent=openIncidents();n.hidden=!openIncidents();if(['photos','overview'].includes(currentPage))loadPhotosIntoView();}
  const go=page=>{clearTimeout(saveTimer);if(currentPage==='daily')saveDailyFromForm();currentPage=page;render();window.scrollTo({top:0,behavior:'instant'});};
  function readDailyForm(form){if(!form||!dailyTouched)return;let d=getLog(activeDay);d.milkyStage=form.elements.milkyStage.value;d.oysterStage=form.elements.oysterStage.value;d.readings={};for(let t of ['am','pm','eve']){d.readings[t]={};for(let r of ['mt','mh','ot','oh']){d.readings[t][r]=form.elements[t+'-'+r].value;}}d.checks={};for(let k of ['msprayAM','msprayPM','osprayAM','osprayPM','ventilated','clean','bagInspection','hygiene'])d.checks[k]=form.elements[k].checked;d.notes=form.elements.notes.value;d.savedAt=new Date().toISOString();state.daily[activeDay]=d;save();dailyTouched=false;}
  function saveDailyFromForm(){let form=$('#daily-form');if(form){readDailyForm(form);}}
  function download(content,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
  const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
  function csv(rows){return '\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n');}
  function downloadDailyCSV(){let cols=['Day','Date','Milky stage','Oyster stage','Morning milky °C','Morning milky RH','Morning oyster °C','Morning oyster RH','Afternoon milky °C','Afternoon milky RH','Afternoon oyster °C','Afternoon oyster RH','Evening milky °C','Evening milky RH','Evening oyster °C','Evening oyster RH','Milky spray check AM','Milky spray check PM','Oyster spray check AM','Oyster spray check PM','Ventilation','Drainage','Bag inspected','Hygiene','Notes'];let rows=[cols];for(let i=1;i<=state.settings.days;i++){let d=getLog(i);let r=d.readings||{},c=d.checks||{};rows.push([i,dateForDay(i),d.milkyStage,d.oysterStage,...['am','pm','eve'].flatMap(k=>['mt','mh','ot','oh'].map(field=>r[k]?.[field]??'')),...['msprayAM','msprayPM','osprayAM','osprayPM','ventilated','clean','bagInspection','hygiene'].map(key=>c[key]?'Yes':'No'),d.notes]);}download(csv(rows),'MYCO_daily_monitoring.csv','text/csv;charset=utf-8');notify('Daily CSV downloaded');}
  function downloadHarvestCSV(){let rows=[['Date','Bag','Mushroom','Flush','Harvest g','Sold g','Price per kg','Revenue INR','Notes'],...state.harvests.map(h=>[h.date,h.bag,h.bag[0]==='M'?'Milky':'Oyster',h.flush,h.grams,h.sold,h.price,Number(h.sold||0)*Number(h.price||0)/1000,h.note])];download(csv(rows),'MYCO_harvests.csv','text/csv;charset=utf-8');notify('Harvest CSV downloaded');}
  function downloadIncidentCSV(){let rows=[['Date','Bag/zone','Type','Severity','Observation','Action','Follow-up','Status'],...state.incidents.map(x=>[x.date,x.bag,x.type,x.severity,x.observation,x.action,x.followup,x.status])];download(csv(rows),'MYCO_incidents.csv','text/csv;charset=utf-8');notify('Incident CSV downloaded');}
  function openPhotoDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB not available'));return;}let req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{let st=req.result.createObjectStore('photos',{keyPath:'id'});st.createIndex('date','date',{unique:false});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  async function photoOperation(mode,fn){let db=await openPhotoDB();return new Promise((res,rej)=>{let tx=db.transaction('photos',mode),st=tx.objectStore('photos'),r;try{r=fn(st);}catch(e){rej(e);db.close();return;}tx.oncomplete=()=>{db.close();res(r?.result)};tx.onerror=()=>{db.close();rej(tx.error)};tx.onabort=()=>{db.close();rej(tx.error||new Error('Database operation aborted'))};});}
  async function getAllPhotos(){try{return(await photoOperation('readonly',s=>s.getAll()))||[]}catch(e){console.warn(e);notify('Photo storage unavailable in this browser',true);return[];}}
  async function putPhoto(p){await photoOperation('readwrite',s=>s.put(p));}
  async function removePhoto(pid){await photoOperation('readwrite',s=>s.delete(pid));}
  async function clearPhotos(){await photoOperation('readwrite',s=>s.clear());}
  async function compressImage(file){return new Promise((res,rej)=>{const objURL=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(objURL);let factor=Math.min(1,1400/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*factor));canvas.height=Math.max(1,Math.round(img.naturalHeight*factor));let c=canvas.getContext('2d');if(!c){rej(new Error('Canvas unavailable'));return;}c.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>blob?res(blob):rej(new Error('Image compression failed')),'image/jpeg',.78);};img.onerror=()=>{URL.revokeObjectURL(objURL);rej(new Error('Unsupported photo format; try JPEG or PNG'))};img.src=objURL;});}
  async function refreshPhotos(){let local=await getAllPhotos(), localIDs=new Set(local.map(p=>p.id));latestPhotos=[...local,...remotePhotos.filter(p=>!localIDs.has(p.id))].sort((a,b)=>String(b.created).localeCompare(String(a.created)));}
  async function loadPhotosIntoView(){try{await refreshPhotos();if(!['photos','overview'].includes(currentPage))return;for(let p of latestPhotos){if(p.blob){photoUrls.push({id:p.id,url:URL.createObjectURL(p.blob),objectUrl:true});}else if(p.remotePath&&cloudUser){try{photoUrls.push({id:p.id,url:await cloud.signedUrl(p.remotePath),objectUrl:false});}catch(e){console.warn('Photo access:',e.message);}}}const html=currentPage==='photos'?latestPhotos.map(photoTile).join(''):latestPhotos.slice(0,4).map(photoTile).join('');if(currentPage==='photos'){let el=$('#photo-list');if(el)el.innerHTML=html?`<div class="photo-grid">${html}</div>`:empty('📷','No saved photos','Add photos using the form above.');}else{let sections=$$('.panel');let panel=sections.find(x=>x.querySelector('[data-go="photos"]'));if(panel){let slot=panel.querySelector('.photo-grid, .empty');if(slot){let wrap=document.createElement('div');wrap.innerHTML=html?`<div class="photo-grid">${html}</div>`:empty('📷','Capture your baseline','Add images of the roof, each zone, and each grow bag.');slot.replaceWith(wrap.firstElementChild);}}}}catch(e){console.error(e);}}
  function fileToDataURL(blob){return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob);});}
  function dataURLtoBlob(uri){let [meta,b64]=uri.split(',');if(!meta?.startsWith('data:image/')||!b64)throw new Error('Invalid image data');let data=atob(b64),bytes=new Uint8Array(data.length);for(let i=0;i<data.length;i++)bytes[i]=data.charCodeAt(i);return new Blob([bytes],{type:meta.match(/data:([^;]+)/)?.[1]||'image/jpeg'});}
  async function exportBackup(){try{notify('Preparing complete backup including photos…');await refreshPhotos();let images=latestPhotos;let packed=[];for(let p of images){let blob=p.blob;if(!blob&&p.remotePath)blob=await cloud.downloadPhoto(p.remotePath);if(!blob)throw new Error('Missing photo '+p.id);packed.push({...p,blob:undefined,imageData:await fileToDataURL(blob)});}let payload={app:'MYCO Field Lab',schemaVersion:1,exportedAt:new Date().toISOString(),data:state,photos:packed};download(JSON.stringify(payload),'MYCO_FULL_BACKUP_'+dateLocal()+'.json','application/json');notify(`Backup downloaded · ${images.length} photos included`);}catch(e){notify('Backup failed: '+e.message,true);}}
  async function importBackup(file){let payload;try{payload=JSON.parse(await file.text());if(payload.app!=='MYCO Field Lab'||payload.schemaVersion!==1||!payload.data?.settings||!payload.data?.daily||!payload.data?.bags||!Array.isArray(payload.photos))throw new Error('Not a valid MYCO backup');if(!confirm(`Restore backup exported ${payload.exportedAt||'unknown date'}? This REPLACES all current records and ${latestPhotos.length} device photos. Download your current backup first.`))return;const restored=payload.data;for(let field of ['purchases','setup','incidents','harvests','expenses'])if(!Array.isArray(restored[field]))throw new Error('Backup missing '+field);await clearPhotos();for(let p of payload.photos){if(!p.imageData)continue;await putPhoto({...p,blob:dataURLtoBlob(p.imageData),imageData:undefined});}Object.keys(state).forEach(key=>delete state[key]);Object.assign(state,restored);activeDay=1;if(cloudUser){cloudPaused=true;localStorage.setItem(importedKey(),'yes');cloudError='Imported backup is local only until you explicitly upload it to cloud.';}save();await refreshPhotos();go('overview');notify('Backup restored locally; cloud upload requires confirmation');}catch(e){console.error(e);notify('Import error: '+e.message,true);}}
  function printReport(){const was=currentPage;let printRoot=document.createElement('div');printRoot.id='print-summary';printRoot.style.display='none';document.body.append(printRoot);let td=Object.values(state.bags).reduce((s,b)=>s+Number(b.dryStraw||0),0);printRoot.innerHTML=`<h1>${esc(state.settings.name)}</h1><p>Day 1: ${displayDate(state.settings.startDate)} · ${state.settings.days} days · ${esc(state.settings.location)}</p><h2>Outcome</h2><p>Milky: ${(harvestWeight('M')/1000).toFixed(3)} kg · Oyster: ${(harvestWeight('O')/1000).toFixed(3)} kg · Total: ${(harvestWeight()/1000).toFixed(3)} kg</p><p>Dry substrate: ${(td/1000).toFixed(3)} kg · Fresh/dry yield ratio: ${(100*harvestWeight()/Math.max(1,td)).toFixed(1)}%</p><p>Expenses entered: ${money(allCosts())} · Sales entered: ${money(allSales())}</p><h2>Bag summary</h2><table>${Object.entries(state.bags).map(([bid,b])=>`<tr><td>${bid}</td><td>${esc(b.status)}</td><td>${Math.round(harvestWeight(bid))}g</td><td>${esc(b.note)}</td></tr>`).join('')}</table><h2>Incidents</h2>${state.incidents.map(x=>`<p><b>${displayDate(x.date)} ${esc(x.bag)}:</b> ${esc(x.type)} — ${esc(x.observation)}. Action: ${esc(x.action||'Not recorded')}. Status: ${esc(x.status)}</p>`).join('')||'<p>No incidents</p>'}<p><small>For personal record-keeping; no automated food-safety certification or yield guarantee.</small></p>`;let css=document.createElement('style');css.id='print-style';css.textContent='@media print{#print-summary{display:block!important;font:12px/1.5 Arial;padding:20px}#print-summary h1{font-size:22px}#print-summary h2{font-size:16px;margin-top:18px}#print-summary table{width:100%;border-collapse:collapse}#print-summary td{border:1px solid #ccc;padding:4px}.app-shell{display:none!important}}';document.head.append(css);window.print();setTimeout(()=>{printRoot.remove();css.remove();},1500);}
  async function init(){try{await refreshPhotos();}catch(e){console.warn(e);}render();await initCloud();}
  // Event delegation: navigation, quick actions, dynamic forms.
  document.addEventListener('click',async e=>{
    let goBtn=e.target.closest('[data-page],[data-go]');if(goBtn){go(goBtn.dataset.page||goBtn.dataset.go);return;}
    let db=e.target.closest('[data-day]');if(db){if(currentPage==='daily')saveDailyFromForm();activeDay=Number(db.dataset.day);render();return;}
    if(e.target.closest('#top-backup,#export-backup,#settings-backup,#cloud-backup')){await exportBackup();return;}
    if(e.target.closest('#import-backup')){$('#import-file').click();return;}
    if(e.target.closest('#export-daily')){downloadDailyCSV();return;}
    if(e.target.closest('#export-harvest')){downloadHarvestCSV();return;}
    if(e.target.closest('#export-incidents')){downloadIncidentCSV();return;}
    if(e.target.closest('#print-report')){printReport();return;}
    let add=e.target.closest('#add-purchase');if(add){$('#new-purchase [name=name]').focus();$('#new-purchase').scrollIntoView({behavior:'smooth',block:'center'});return;}
    let delP=e.target.closest('[data-del-purchase]');if(delP){if(confirm('Remove this purchase?')){state.purchases=state.purchases.filter(x=>x.id!==delP.dataset.delPurchase);save();render();}return;}
    let delI=e.target.closest('[data-del-incident]');if(delI){if(confirm('Delete this incident report?')){state.incidents=state.incidents.filter(x=>x.id!==delI.dataset.delIncident);save();render();}return;}
    let delH=e.target.closest('[data-del-harvest]');if(delH){if(confirm('Remove this harvest record?')){state.harvests=state.harvests.filter(x=>x.id!==delH.dataset.delHarvest);save();render();}return;}
    let delE=e.target.closest('[data-del-expense]');if(delE){if(confirm('Remove this expense?')){state.expenses=state.expenses.filter(x=>x.id!==delE.dataset.delExpense);save();render();}return;}
    let delPhoto=e.target.closest('[data-delete-photo]');if(delPhoto){if(confirm('Delete this photo from this device AND private cloud (if synced)?')){try{let p=latestPhotos.find(p=>p.id===delPhoto.dataset.deletePhoto), rp=remotePhotos.find(x=>x.id===p?.id);if(rp&&cloudUser)await cloud.deletePhoto(rp);await removePhoto(delPhoto.dataset.deletePhoto);remotePhotos=remotePhotos.filter(x=>x.id!==delPhoto.dataset.deletePhoto);await refreshPhotos();render();notify('Photo deleted');}catch(err){notify('Cannot delete: '+err.message,true);}}return;}
    let view=e.target.closest('[data-view-photo]');if(view){let p=latestPhotos.find(p=>p.id===view.dataset.viewPhoto);if(p){$('#photo-large').src=photoUrls.find(x=>x.id===p.id)?.url||'';$('#photo-detail').textContent=`${p.bag} · Day ${p.day} · ${displayDate(p.date)} · ${p.caption||''}`;$('#photo-modal').showModal();}return;}
    let quickH=e.target.closest('[data-quick-harvest]');if(quickH){go('reports');$('#harvest-form [name=bag]').value=quickH.dataset.quickHarvest;$('#harvest-form').scrollIntoView({block:'center'});return;}
    let quickPhoto=e.target.closest('[data-quick-photo]');if(quickPhoto){go('photos');$('#photo-bag').value=quickPhoto.dataset.quickPhoto;$('#photo-input').focus();return;}
    if(e.target.closest('#cloud-signout')){if(!confirm('Sign out? Your device will retain cached records and photos. Sign out only on a trusted device.'))return;try{await cloud.signOut();cloudUser=null;cloudPaused=true;remotePhotos=[];cloudStatus('Signed out · Device cache remains');render();notify('Signed out of cloud');}catch(err){notify(err.message,true);}return;}
    if(e.target.closest('#cloud-upload')){try{await uploadLocalToCloud();}catch(err){notify('Cloud upload: '+err.message,true);render();}return;}
    if(e.target.closest('#cloud-load')){try{await loadCloud();}catch(err){notify('Cloud load: '+err.message,true);}return;}
    if(e.target.closest('#cloud-photos')){try{notify('Syncing local photos…');let n=await syncLocalPhotos();notify(n+' photo(s) uploaded');}catch(err){notify('Photo upload: '+err.message,true);}return;}
    if(e.target.closest('#cloud-sync-now')){try{await flushCloud();if(!cloudPaused)await syncLocalPhotos();}catch(err){notify('Sync: '+err.message,true);}return;}
    if(e.target.closest('#reset-data')){if(!confirm('Reset all local records and photos? Export a backup before proceeding.'))return;if(!confirm('FINAL CONFIRMATION: erase the current project in this browser?'))return;try{await clearPhotos();localStorage.removeItem(KEY);location.reload();}catch(err){notify(err.message,true);}return;}
  });
  document.addEventListener('change',e=>{
    if(e.target.matches('[data-purch-check]')){let p=state.purchases.find(x=>x.id===e.target.dataset.purchCheck);if(p){p.done=e.target.checked;save();render();}return;}
    if(e.target.matches('[data-purch-cost],[data-purch-actual]')){let pid=e.target.dataset.purchCost||e.target.dataset.purchActual;let p=state.purchases.find(x=>x.id===pid);if(p){if(e.target.dataset.purchCost)p.estimated=Math.max(0,Number(e.target.value)||0);else p.actual=e.target.value===''?'':Math.max(0,Number(e.target.value)||0);save();render();}return;}
    if(e.target.matches('[data-setup-check]')){let s=state.setup.find(x=>x.id===e.target.dataset.setupCheck);if(s){s.done=e.target.checked;save();render();}return;}
    if(e.target.matches('[data-bag-field]')){let b=state.bags[e.target.dataset.bag];if(b){b[e.target.dataset.bagField]=e.target.value;save();if(e.target.dataset.bagField==='status')render();}return;}
    if(e.target.matches('[data-incident-status]')){let i=state.incidents.find(x=>x.id===e.target.dataset.incidentStatus);if(i){i.status=e.target.value;save();render();}return;}
    if(e.target.matches('#photo-filter')){let f=e.target.value,list=latestPhotos.filter(p=>f==='all'||String(p.day)===f);$('#photo-list').innerHTML=list.length?`<div class="photo-grid">${list.map(photoTile).join('')}</div>`:empty('📷','No images for this day','Choose a different day or add one using the form.');return;}
    if(e.target.closest('#daily-form')){dailyTouched=true;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveDailyFromForm();$('#daily-save-hint').textContent='Auto-saved locally';},250);return;}
  });
  document.addEventListener('input',e=>{if(e.target.closest('#daily-form')){dailyTouched=true;let hint=$('#daily-save-hint');if(hint)hint.textContent='Saving changes…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveDailyFromForm();let hint2=$('#daily-save-hint');if(hint2)hint2.textContent='Auto-saved locally';},550);}});
  document.addEventListener('submit',async e=>{
    let f=e.target;if(!['new-purchase','daily-form','photo-form','incident-form','harvest-form','expense-form','settings-form','cloud-config','cloud-login'].includes(f.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(f).entries());
    if(f.id==='cloud-config'){try{cloud.saveConfig(v.url,v.key);notify('Cloud project saved; refreshing connection…');location.reload();}catch(err){notify(err.message,true);}return;}
    if(f.id==='cloud-login'){try{await cloud.signIn(v.email.trim());notify('Sign-in email sent. Open the link to connect your farm.');}catch(err){notify('Sign-in failed: '+err.message,true);}return;}
    if(f.id==='new-purchase'){state.purchases.push({id:'new'+id(),category:'Extra',name:v.name.trim(),quantity:v.quantity||'1',estimated:Number(v.estimated)||0,actual:'',done:false});save();render();notify('Added purchase item');}
    if(f.id==='daily-form'){dailyTouched=true;saveDailyFromForm();render();notify(`Day ${activeDay} recorded`);}
    if(f.id==='incident-form'){state.incidents.push({id:id(),date:v.date,bag:v.bag,type:v.type,severity:v.severity,observation:v.observation.trim(),action:v.action||'',followup:v.followup||'',status:v.status});save();render();notify('Abnormality report saved');}
    if(f.id==='harvest-form'){if(Number(v.sold)>Number(v.grams)){notify('Sold grams cannot exceed fresh harvested grams',true);return;}state.harvests.push({...v,id:id(),grams:Number(v.grams)||0,sold:Number(v.sold)||0,price:Number(v.price)||0,flush:Number(v.flush)||1});save();render();notify('Harvest added');}
    if(f.id==='expense-form'){state.expenses.push({...v,id:id(),amount:Number(v.amount)||0});save();render();notify('Expense saved');}
    if(f.id==='settings-form'){let newDays=Math.round(Number(v.days));if(newDays<30||newDays>90){notify('Duration must be between 30 and 90 days',true);return;}if(newDays<Math.max(0,...Object.keys(state.daily).map(Number))&&!confirm('Shortening the trial hides existing later daily records. Continue?'))return;Object.assign(state.settings,{name:v.name.trim(),startDate:v.startDate,days:newDays,location:v.location,notes:v.notes});activeDay=Math.max(1,Math.min(newDays,activeDay));save();render();notify('Trial settings updated');}
    if(f.id==='photo-form'){let files=Array.from($('#photo-input').files||[]);if(!files.length){notify('Choose at least one photo',true);return;}if(files.length>12){notify('Add up to 12 photos at a time',true);return;}let status=$('#photo-status');if(status)status.textContent='Processing photos…';try{for(let file of files){let blob=await compressImage(file),day=Number(v.day);await putPhoto({id:id(),day,bag:v.bag,date:dateForDay(day),caption:v.caption||'',created:new Date().toISOString(),blob,originalName:file.name});}await refreshPhotos();if(cloudUser){try{await syncLocalPhotos();notify(`${files.length} photo(s) saved locally and in cloud`);}catch(e){notify('Photos stored locally. Cloud upload pending: '+e.message,true);}}else notify(`${files.length} photo(s) saved on this device`);render();}catch(err){console.error(err);notify('Could not save photo: '+err.message,true);}}
  });
  $('#import-file').addEventListener('change',async e=>{let f=e.target.files[0];if(f)await importBackup(f);e.target.value='';});
  $('#close-photo').addEventListener('click',()=>$('#photo-modal').close());
  $('#photo-modal').addEventListener('click',e=>{if(e.target===$('#photo-modal'))$('#photo-modal').close();});
  if('serviceWorker'in navigator &&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
  window.addEventListener('beforeunload',()=>{if(currentPage==='daily')saveDailyFromForm();});
  init();
})();
